        title = LocalizedText("""Novena a la Inmaculada Concepción""", """Immaculate Conception Novena""", """Novena à Imaculada Conceição - Pureza e Virtude"""),
        patron = LocalizedText("""Santo patrón de Estados Unidos""", """Patron saint of United States""", """Novena à Imaculada Conceição - Pureza e Virtude"""),
        category = LocalizedText("""Novenas""", """Novenas""", """Novenas"""),
        description = LocalizedText("""Nuestra Señora se apareció a Santa Bernardita en Lourdes, Francia, y confirmó que ella era “la Inmaculada Concepción”.""", """Our Lady appeared to St. Bernadette in Lourdes, France and confirmed that she was “the Immaculate Conception.”""", """Nossa Senhora apareceu a Santa Bernadette em Lourdes, França e confirmou que ela era ‘a Imaculada Conceição’."""),
